begin;
alter table public.rollover_execution_handler_registry drop constraint rollover_execution_handler_registry_mutation_class_check;
alter table public.rollover_execution_handler_registry add constraint rollover_execution_handler_registry_mutation_class_check check(mutation_class in('read_only','contract_domain','roster_domain','taxi_domain','taxi_eligibility_domain','ir_domain','draft_inventory_domain','rookie_authority_domain','rookie_eligibility_domain','dead_cap_domain'));
insert into public.rollover_execution_handler_registry(operation_code,operation_order,handler_version,input_schema_version,result_schema_version,execution_owner,mutation_class,metadata) values('APPLY_DEAD_CAP_OBLIGATIONS',22,1,'phase3b10a-dead-cap-input-v1','phase3b10a-dead-cap-result-v1','execution','dead_cap_domain',jsonb_build_object('phase','3B.10A','cap_calculation',false,'publication',false));
do $$declare d text;sig regprocedure;begin foreach sig in array array['public.guard_contract_write_during_rollover()'::regprocedure,'public.guard_season_roster_assignment_insert_phase3b8a()'::regprocedure,'public.guard_phase3b9a_draft_inventory()'::regprocedure,'public.guard_phase3b9b_rookie_authority()'::regprocedure,'public.guard_phase3b9c_rookie_eligibility()'::regprocedure] loop select pg_get_functiondef(sig) into d;d:=replace(d,'''phase3b9c-v1'')','''phase3b9c-v1'',''phase3b10a-v1'')');execute d;end loop;end$$;
create table public.rollover_dead_cap_obligations(id uuid primary key default gen_random_uuid(),rollover_execution_id uuid not null references public.rollover_executions(id),operation_code text not null check(operation_code='APPLY_DEAD_CAP_OBLIGATIONS'),league_id uuid not null references public.leagues(id),target_season_id uuid not null references public.league_seasons(id),league_team_id uuid not null references public.league_teams(id),player_id text not null references public.player_universe(sleeper_id),contract_agreement_id uuid not null references public.contract_agreements(id),release_id uuid not null references public.rollover_contract_releases(id),hold_id uuid references public.rollover_commissioner_holds(id),source_event_id uuid not null references public.contract_events(id),obligation_source text not null check(obligation_source='certified_contract_event'),obligation_reason text not null,amount numeric(12,2) not null check(amount>0),effective_season integer not null,obligation_status text not null check(obligation_status='prepared'),published_at timestamptz,superseded_at timestamptz,schema_version text not null check(schema_version='phase3b10a-dead-cap-v1'),source_snapshot_hash text not null check(source_snapshot_hash~'^[0-9a-f]{64}$'),deterministic_fingerprint text not null check(deterministic_fingerprint~'^[0-9a-f]{64}$'),created_at timestamptz not null default clock_timestamp(),unique(rollover_execution_id,contract_agreement_id,obligation_reason),unique(rollover_execution_id,source_event_id),check(published_at is null and superseded_at is null));
alter table public.rollover_dead_cap_obligations enable row level security;revoke all on public.rollover_dead_cap_obligations from public,anon,authenticated;grant select,insert on public.rollover_dead_cap_obligations to service_role;create policy dead_cap_commissioner_read on public.rollover_dead_cap_obligations for select to authenticated using(exists(select 1 from public.league_memberships m where m.league_id=rollover_dead_cap_obligations.league_id and m.user_id=auth.uid() and m.role='commissioner'));
create or replace function public.guard_phase3b10a_dead_cap() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$declare lid uuid:=coalesce(new.league_id,old.league_id);begin if tg_op in('UPDATE','DELETE') then raise exception 'dead_cap_obligation_immutable';end if;if public.has_active_rollover_cutover_lock(lid) and coalesce(current_setting('app.rollover_typed_execution',true),'') not in('phase3b7c-v1','phase3b8a-v1','phase3b8b-v1','phase3b8c-v1','phase3b8d-v1','phase3b9a-v1','phase3b9b-v1','phase3b9c-v1','phase3b10a-v1') then raise exception 'rollover_cutover_dead_cap_writes_blocked';end if;return new;end$$;
create trigger rollover_dead_cap_obligations_guard before insert or update or delete on public.rollover_dead_cap_obligations for each row execute function public.guard_phase3b10a_dead_cap();

create or replace function public.write_dead_cap_phase3b10a_private(p_rollover_execution_id uuid,p_execution_plan_id uuid,p_approval_id uuid,p_actor uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare x public.rollover_executions%rowtype;s public.rollover_execution_input_snapshots%rowtype;r public.rollover_contract_releases%rowtype;h public.rollover_commissioner_holds%rowtype;e public.contract_events%rowtype;amount numeric;reason text;fp text;written int:=0;reused int:=0;released_count int:=0;hold_count int:=0;source_count int:=0;sethash text;
begin select * into x from public.rollover_executions where id=p_rollover_execution_id;if x.id is null then perform public.raise_phase3b6c1_failure('dead_cap_execution_missing','{}');end if;if not exists(select 1 from public.rollover_execution_locks l where l.rollover_execution_id=x.id and l.execution_plan_id=p_execution_plan_id and l.approval_id=p_approval_id and l.status='active' and l.lock_type='cutover' for update) then perform public.raise_phase3b6c1_failure('dead_cap_cutover_lock_missing','{}');end if;select * into s from public.rollover_execution_input_snapshots where rollover_execution_id=x.id and execution_plan_id=p_execution_plan_id and approval_id=p_approval_id for share;if s.id is null then perform public.raise_phase3b6c1_failure('dead_cap_snapshot_mismatch','{}');end if;
 perform 1 from public.contract_agreements where league_id=x.league_id order by id for share;perform 1 from public.contract_events where league_id=x.league_id and event_type='dead_cap_created' order by contract_id,id for share;perform 1 from public.rollover_contract_releases where rollover_execution_id=x.id order by contract_agreement_id,id for share;perform 1 from public.rollover_commissioner_holds where rollover_execution_id=x.id order by source_contract_agreement_id,id for share;perform 1 from public.rollover_dead_cap_obligations where rollover_execution_id=x.id order by contract_agreement_id,id for update;
 for r in select * from public.rollover_contract_releases where rollover_execution_id=x.id order by contract_agreement_id loop
  if(select count(*) from public.contract_events where contract_id=r.contract_agreement_id and event_type='dead_cap_created' and effective_season=r.effective_season)>1 then perform public.raise_phase3b6c1_failure('dead_cap_duplicate_obligation','{}');end if;select * into e from public.contract_events where contract_id=r.contract_agreement_id and event_type='dead_cap_created' and effective_season=r.effective_season;if e.id is null then continue;end if;source_count:=source_count+1;if e.league_id<>x.league_id or e.league_team_id<>r.source_league_team_id or e.player_id<>r.player_id then perform public.raise_phase3b6c1_failure('dead_cap_cross_league_or_owner_conflict','{}');end if;amount:=nullif(e.metadata->>'dead_cap_amount','')::numeric;reason:=nullif(e.metadata->>'penalty_rule','');if amount is null or amount<=0 then perform public.raise_phase3b6c1_failure('dead_cap_invalid_amount','{}');end if;if reason is null then perform public.raise_phase3b6c1_failure('dead_cap_missing_outcome','{}');end if;select * into h from public.rollover_commissioner_holds where rollover_execution_id=x.id and source_contract_agreement_id=r.contract_agreement_id and hold_status='active';fp:=public.rollover_material_fingerprint(jsonb_build_object('schema','phase3b10a-dead-cap-v1','execution',x.id,'release',r.release_fingerprint,'hold',h.creation_fingerprint,'event',to_jsonb(e)-'created_at'-'effective_at','amount',amount,'reason',reason,'snapshot',s.aggregate_snapshot_fingerprint));if exists(select 1 from public.rollover_dead_cap_obligations where rollover_execution_id=x.id and contract_agreement_id=r.contract_agreement_id and deterministic_fingerprint<>fp) then perform public.raise_phase3b6c1_failure('dead_cap_fingerprint_mismatch','{}');end if;insert into public.rollover_dead_cap_obligations(rollover_execution_id,operation_code,league_id,target_season_id,league_team_id,player_id,contract_agreement_id,release_id,hold_id,source_event_id,obligation_source,obligation_reason,amount,effective_season,obligation_status,schema_version,source_snapshot_hash,deterministic_fingerprint) values(x.id,'APPLY_DEAD_CAP_OBLIGATIONS',x.league_id,r.target_season_id,r.source_league_team_id,r.player_id,r.contract_agreement_id,r.id,h.id,e.id,'certified_contract_event',reason,amount,r.effective_season,'prepared','phase3b10a-dead-cap-v1',s.aggregate_snapshot_fingerprint,fp) on conflict(rollover_execution_id,contract_agreement_id,obligation_reason) do nothing;if found then written:=written+1;else reused:=reused+1;end if;if h.id is null then released_count:=released_count+1;else hold_count:=hold_count+1;end if;end loop;
 sethash:=public.rollover_material_fingerprint((select jsonb_agg(jsonb_build_object('agreement',o.contract_agreement_id,'hash',o.deterministic_fingerprint) order by o.contract_agreement_id) from public.rollover_dead_cap_obligations o where o.rollover_execution_id=x.id));return jsonb_build_object('certified_source_event_count',source_count,'prepared_obligation_count',written,'compatible_replay_count',reused,'released_obligation_count',released_count,'commissioner_hold_obligation_count',hold_count,'continuing_contract_obligation_count',0,'total_prepared_amount',(select coalesce(sum(o.amount),0) from public.rollover_dead_cap_obligations o where o.rollover_execution_id=x.id),'obligation_set_hash',sethash,'mutation_count',written,'postcondition_count',7,'validation_codes',jsonb_build_array('certified_events_only','release_linkage','hold_linkage','positive_amount','immutable_unpublished','no_cap_calculation','cutover_lock'));end$$;
create or replace function public.execute_rollover_typed_handler_phase3b10a_private(p_operation jsonb,p_rollover_execution_id uuid,p_execution_plan_id uuid,p_approval_id uuid,p_actor uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare code text:=p_operation->>'operation_type';result jsonb;begin if code<>'APPLY_DEAD_CAP_OBLIGATIONS' then return public.execute_rollover_typed_handler_phase3b9c_private(p_operation,p_rollover_execution_id,p_execution_plan_id,p_approval_id,p_actor);end if;if(p_operation->>'operation_index')::int<>22 then perform public.raise_phase3b6c1_failure('unsupported_handler_version','{}');end if;result:=public.write_dead_cap_phase3b10a_private(p_rollover_execution_id,p_execution_plan_id,p_approval_id,p_actor);return jsonb_build_object('operation_code',code,'handler_version',1,'result',result||jsonb_build_object('operation_mutation_count',coalesce((result->>'mutation_count')::int,0)));end$$;
do $$declare d text;begin select pg_get_functiondef('public.execute_rollover_plan_phase3b9c_private(jsonb,uuid)'::regprocedure) into d;d:=replace(d,'execute_rollover_plan_phase3b9c_private','execute_rollover_plan_phase3b10a_private');d:=replace(d,'execute_rollover_typed_handler_phase3b9c_private','execute_rollover_typed_handler_phase3b10a_private');d:=replace(d,'''REFRESH_ROOKIE_ELIGIBILITY'')','''REFRESH_ROOKIE_ELIGIBILITY'',''APPLY_DEAD_CAP_OBLIGATIONS'')');d:=replace(d,'Phase 3B.9C','Phase 3B.10A');d:=replace(d,'phase3b9c-v1','phase3b10a-v1');execute d;end$$;
create or replace function public.execute_rollover_plan_authenticated(p_request jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare actor uuid:=public.require_authenticated_user();x public.rollover_executions%rowtype;begin if p_request?'actor_user_id' or p_request?'executed_by' then raise exception 'actor spoofing forbidden';end if;select * into x from public.rollover_executions where id=(p_request->>'rollover_execution_id')::uuid;if x.id is null then raise exception 'execution not found';end if;perform public.require_commissioner_authority(x.league_id);return public.execute_rollover_plan_phase3b10a_private(p_request,actor);end$$;
revoke all on function public.write_dead_cap_phase3b10a_private(uuid,uuid,uuid,uuid),public.execute_rollover_typed_handler_phase3b10a_private(jsonb,uuid,uuid,uuid,uuid),public.execute_rollover_plan_phase3b10a_private(jsonb,uuid),public.guard_phase3b10a_dead_cap() from public,anon,authenticated,service_role;revoke all on function public.execute_rollover_plan_authenticated(jsonb) from public,anon,authenticated,service_role;grant execute on function public.execute_rollover_plan_authenticated(jsonb) to authenticated;
commit;
